package org.dextur.reputation.paper;

import java.time.*;
import java.util.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.PlayerLanguage;
import org.dextur.reputation.domain.investigation.InvestigationData.*;

/** Administrative boundary: permissions and known-player facts are captured only on Paper main thread. */
final class InvestigationCommands implements CommandExecutor,TabCompleter {
    private static final Set<String> ROOTS=Set.of("inspect","history","vote","invalidate","restore","pending","trust","flags","flag","relations","recalculate","audit","gui","bulk","confirm");
    final DexturReputationPlugin plugin;final ReputationApplication profiles;final InvestigationApplication app;final Settings settings;final Messages messages;final PolicyCommands previous;InvestigationGui gui;
    InvestigationCommands(DexturReputationPlugin plugin,ReputationApplication profiles,InvestigationApplication app,Settings settings,Messages messages,PolicyCommands previous){this.plugin=plugin;this.profiles=profiles;this.app=app;this.settings=settings;this.messages=messages;this.previous=previous;}
    PlayerLanguage language(CommandSender sender){return previous.language(sender);}
    void send(CommandSender sender,String key,Map<String,String> values){previous.send(sender,key,values);}
    boolean permitted(CommandSender sender,String node){if(sender.hasPermission("dexturreputation.admin."+node))return true;send(sender,"no-permission",Map.of());return false;}
    static String permission(Action action){return switch(action){case INVALIDATE->"vote.invalidate";case RESTORE->"vote.restore";case APPROVE->"pending.approve";case REJECT->"pending.reject";case RECALCULATE_REPUTATION->"recalculate.reputation";case RECALCULATE_TRUST->"recalculate.trust";case RECALCULATE_TIER->"recalculate.tier";case RECALCULATE_ALL->"recalculate.all";case RESOLVE_FLAG->"flags.resolve";};}
    static String permission(Section section){return switch(section){case INSPECT,RECALCULATE->"inspect";case VOTE->"vote.inspect";case PENDING->"pending.view";case TRUST,TRUST_HISTORY->"trust.inspect";case FLAGS->"flags.inspect";case RELATIONS->"relations.inspect";case AUDIT,OPERATION->"audit";case BULKS->"bulk";default->"history";};}
    UUID resolve(CommandSender sender,String value){if(value.length()>64)throw new IllegalArgumentException("INV_INPUT");try{UUID id=UUID.fromString(value);var p=plugin.getServer().getOfflinePlayer(id);if(p.isOnline()||p.hasPlayedBefore())return id;}catch(IllegalArgumentException ignored){}var online=plugin.getServer().getPlayerExact(value);var known=online==null?plugin.getServer().getOfflinePlayerIfCached(value):online;if(known!=null&&(known.isOnline()||known.hasPlayedBefore()))return known.getUniqueId();throw new IllegalArgumentException("INV_UNKNOWN");}
    static UUID id(String value){if(!value.matches("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"))throw new IllegalArgumentException("INV_ID");return UUID.fromString(value);}
    String actor(CommandSender sender){return sender instanceof Player p?p.getUniqueId().toString():"CONSOLE";}
    void failed(CommandSender sender,Throwable error){while(error.getCause()!=null&&error.getCause()!=error)error=error.getCause();String code=error.getMessage();String key=code!=null&&code.startsWith("INV_")?"admin7-error-"+code.substring(4).toLowerCase(Locale.ROOT):error instanceof IllegalArgumentException?"admin7-error-input":"admin7-error-storage";try{send(sender,key,Map.of());}catch(IllegalArgumentException missing){send(sender,"admin7-error-storage",Map.of());}if(key.equals("admin7-error-storage"))plugin.logFailure("investigation",error);}
    Request request(CommandSender sender,Action action,UUID subject,String reason,long revision,String resolution){return new Request(UUID.randomUUID(),settings.scope(),action,subject,actor(sender),reason,revision,resolution,app.now());}
    void mutate(CommandSender sender,Request request,Runnable done){if(!permitted(sender,permission(request.action())))return;app.mutate(request).whenComplete((result,error)->plugin.onMain(()->{if(error!=null)failed(sender,error);else{send(sender,"admin7-applied",Map.of("operation",result.operation().toString(),"status",translated(sender,result.status()),"value",Long.toString(result.profile().visibleScore())));}done.run();}));}
    private String reason(String[] args,int start){String text=String.join(" ",Arrays.stream(args).skip(start).filter(a->!a.startsWith("--")).toList());if(text.startsWith("\"")&&text.endsWith("\"")&&text.length()>=2)text=text.substring(1,text.length()-1);return org.dextur.reputation.domain.investigation.InvestigationData.clean(text,1000);}
    private int page(String[] args){for(String a:args)if(a.startsWith("--page="))return Integer.parseInt(a.substring(7));return 1;}
    Filter filter(CommandSender sender,String[] args){UUID voter=null,target=null,flag=null;org.dextur.reputation.api.VoteType type=null;String status="",severity="",source="",search="";Instant before=null,after=null;
        for(String arg:args)if(arg.startsWith("--")){String[] pair=arg.substring(2).split("=",2);if(pair[0].equals("dry-run"))continue;if(pair.length!=2)throw new IllegalArgumentException("INV_FILTER");String value=pair[1];switch(pair[0]){case "page"->{}case "voter"->voter=resolve(sender,value);case "target","player"->target=resolve(sender,value);case "flag"->flag=id(value);case "type"->type=switch(value.toUpperCase(Locale.ROOT)){case "LIKE","POSITIVE"->org.dextur.reputation.api.VoteType.POSITIVE;case "DISLIKE","NEGATIVE"->org.dextur.reputation.api.VoteType.NEGATIVE;default->throw new IllegalArgumentException("INV_FILTER");};case "status"->status=value.toUpperCase(Locale.ROOT);case "severity"->severity=value.toUpperCase(Locale.ROOT);case "source"->source=value.toUpperCase(Locale.ROOT);case "search"->search=value;case "min-age"->before=age(value);case "max-age"->after=age(value);default->throw new IllegalArgumentException("INV_FILTER");}}
        return new Filter(voter,target,type,status,before,after,severity,source,flag,search);
    }
    private Instant age(String value){long seconds=Long.parseLong(value);if(seconds<0||seconds>315360000)throw new IllegalArgumentException("INV_FILTER");return app.now().minusSeconds(seconds);}
    void read(CommandSender sender,Section section,UUID player,UUID operation,String[] args){if(!permitted(sender,permission(section)))return;var query=new Query(section,settings.scope(),player,operation,filter(sender,args),page(args),app.rules().pageSize());app.read(query).whenComplete((report,error)->plugin.onMain(()->{if(!sender.hasPermission("dexturreputation.admin."+permission(section)))return;if(error!=null)failed(sender,error);else render(sender,report,section);}));}
    String label(CommandSender sender,String key){try{return messages.plain(language(sender),"admin7-field-"+key);}catch(IllegalArgumentException missing){return key;}}
    String translated(CommandSender sender,String value){try{return messages.plain(language(sender),"admin7-value-"+value.toLowerCase(Locale.ROOT));}catch(IllegalArgumentException missing){return value;}}
    private static String bounded(String text,int limit){return text.length()<=limit?text:text.substring(0,limit)+"…";}
    private void fullField(CommandSender sender,String field,String value){if(value.isEmpty()){send(sender,"admin7-field",Map.of("field",field,"value",value));return;}int start=0;while(start<value.length()){int end=value.offsetByCodePoints(start,Math.min(1000,value.codePointCount(start,value.length())));send(sender,"admin7-field",Map.of("field",field,"value",value.substring(start,end)));start=end;}}
    String detail(CommandSender sender,Map<String,String> values,int maximum){var text=new StringBuilder();for(var e:new TreeMap<>(values).entrySet()){if(Set.of("plan","request_hash","schema").contains(e.getKey()))continue;if(!text.isEmpty())text.append(" | ");text.append(label(sender,e.getKey())).append(": ").append(translated(sender,e.getValue()));if(text.length()>maximum){text.setLength(maximum);text.append("…");break;}}return text.toString();}
    void render(CommandSender sender,Report report,Section section){send(sender,"admin7-report",Map.of("section",messages.plain(language(sender),"admin7-section-"+section.name().toLowerCase(Locale.ROOT)),"total",Long.toString(report.total()),"page",report.summary().getOrDefault("page","1")));var summary=new TreeMap<>(report.summary());if(summary.containsKey("uuid")){try{var p=plugin.getServer().getOfflinePlayer(UUID.fromString(summary.get("uuid")));summary.put("name",Objects.toString(p.getName(),"—"));}catch(IllegalArgumentException ignored){}}
        for(var e:summary.entrySet())send(sender,"admin7-field",Map.of("field",label(sender,e.getKey()),"value",bounded(translated(sender,e.getValue()),1000)));
        for(var row:report.rows())if(section==Section.VOTE||section==Section.OPERATION){for(var e:new TreeMap<>(row.values()).entrySet())fullField(sender,label(sender,e.getKey()),translated(sender,e.getValue()));}else send(sender,"admin7-row",Map.of("id",row.id().toString(),"details",detail(sender,row.values(),1000)));
        if(report.rows().isEmpty()&&report.summary().isEmpty())send(sender,"admin7-empty",Map.of());
    }
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(args.length==0){previous.onCommand(sender,command,label,args);if(sender.hasPermission("dexturreputation.admin.inspect"))send(sender,"admin7-help",Map.of());return true;}if(!ROOTS.contains(args[0].toLowerCase(Locale.ROOT)))return previous.onCommand(sender,command,label,args);if(!plugin.ready()){send(sender,"unavailable",Map.of());return true;}
        try{if(args.length>80||Arrays.stream(args).mapToInt(String::length).sum()>4096)throw new IllegalArgumentException("INV_INPUT");if(actor(sender).equals("CONSOLE")&&!app.rules().consoleAllowed())throw new IllegalArgumentException("INV_CONSOLE");String root=args[0].toLowerCase(Locale.ROOT);
            if(root.equals("confirm")){if(args.length!=2||!permitted(sender,"bulk"))return true;var action=app.confirmationAction(args[1],actor(sender));if(action.isEmpty())throw new IllegalArgumentException("INV_TOKEN");if(!permitted(sender,permission(action.get())))return true;app.confirmationOperation(args[1],actor(sender)).ifPresent(operation->send(sender,"admin7-bulk-started",Map.of("operation",operation.toString())));finishBulk(sender,app.confirm(args[1],actor(sender)));return true;}
            if(root.equals("bulk")){bulk(sender,args);return true;}
            if(root.equals("pending")&&args.length>=3&&Set.of("approve","reject").contains(args[1].toLowerCase(Locale.ROOT))){Action action=args[1].equalsIgnoreCase("approve")?Action.APPROVE:Action.REJECT;mutate(sender,request(sender,action,id(args[2]),reason(args,3),-1,""),()->{});return true;}
            if(root.equals("invalidate")||root.equals("restore")){if(args.length<2)throw new IllegalArgumentException("INV_INPUT");Action action=root.equals("invalidate")?Action.INVALIDATE:Action.RESTORE;mutate(sender,request(sender,action,id(args[1]),reason(args,2),-1,""),()->{});return true;}
            if(root.equals("flag")){if(args.length<3)throw new IllegalArgumentException("INV_INPUT");mutate(sender,request(sender,Action.RESOLVE_FLAG,id(args[1]),reason(args,3),-1,args[2].toUpperCase(Locale.ROOT)),()->{});return true;}
            if(root.equals("recalculate")){if(args.length<3)throw new IllegalArgumentException("INV_INPUT");Action action=Action.valueOf("RECALCULATE_"+args[1].toUpperCase(Locale.ROOT));mutate(sender,request(sender,action,resolve(sender,args[2]),args.length>3?reason(args,3):messages.plain(language(sender),"admin7-recalculate-reason"),-1,""),()->{});return true;}
            if(root.equals("vote")){if(args.length<2)throw new IllegalArgumentException("INV_INPUT");read(sender,Section.VOTE,null,id(args[1]),args);return true;}
            if(root.equals("audit")&&args.length>2&&args[1].equalsIgnoreCase("operation")){read(sender,Section.OPERATION,null,id(args[2]),args);return true;}
            if(root.equals("pending")){UUID player=args.length>1&&!args[1].startsWith("--")?resolve(sender,args[1]):null;read(sender,Section.PENDING,player,null,args);return true;}
            if(args.length<2)throw new IllegalArgumentException("INV_INPUT");UUID player=resolve(sender,args[1]);
            if(root.equals("gui")){if(!permitted(sender,"gui"))return true;if(sender instanceof Player p)gui.open(p,player,Section.INSPECT,1);else send(sender,"players-only",Map.of());return true;}
            Section section=switch(root){case "inspect"->Section.INSPECT;case "history"->args.length>2&&!args[2].startsWith("--")?switch(args[2].toLowerCase(Locale.ROOT)){case "votes"->Section.VOTES;case "admin"->Section.ADMIN;case "trust"->Section.TRUST_HISTORY;case "recovery"->Section.RECOVERY;case "flags"->Section.FLAGS;default->throw new IllegalArgumentException("INV_INPUT");}:Section.VOTES;case "trust"->Section.TRUST;case "flags"->Section.FLAGS;case "relations"->Section.RELATIONS;case "audit"->Section.AUDIT;default->throw new IllegalArgumentException("INV_INPUT");};if(root.equals("history")&&!permitted(sender,"history"))return true;read(sender,section,player,null,args);
        }catch(RuntimeException error){failed(sender,error);}return true;
    }
    private void finishBulk(CommandSender sender,java.util.concurrent.CompletionStage<org.dextur.reputation.domain.investigation.InvestigationData.Record> operation){operation.whenComplete((result,error)->plugin.onMain(()->{if(error!=null)failed(sender,error);else send(sender,"admin7-bulk-result",Map.of("operation",result.id().toString(),"status",translated(sender,result.status()),"completed",result.values().get("cursor"),"total",Integer.toString(result.related().size())));}));}
    private void bulk(CommandSender sender,String[] args){if(!permitted(sender,"bulk"))return;if(args.length<3)throw new IllegalArgumentException("INV_SCOPE");if(Set.of("resume","cancel","status").contains(args[1].toLowerCase(Locale.ROOT))){UUID operation=id(args[2]);if(args[1].equalsIgnoreCase("status")){read(sender,Section.OPERATION,null,operation,args);return;}app.read(new Query(Section.OPERATION,settings.scope(),null,operation,Filter.empty(),1,1)).whenComplete((report,error)->plugin.onMain(()->{if(error!=null){failed(sender,error);return;}var record=report.rows().stream().filter(row->row.values().containsKey("cursor")).findFirst().orElse(null);if(record==null){failed(sender,new IllegalArgumentException("INV_UNKNOWN"));return;}Action action=Action.valueOf(record.values().get("action"));if(permitted(sender,"bulk")&&permitted(sender,permission(action)))finishBulk(sender,args[1].equalsIgnoreCase("resume")?app.resume(operation,actor(sender)):app.cancel(operation,actor(sender)));}));return;}
        Action action=switch(args[1].toLowerCase(Locale.ROOT)){case "invalidate"->Action.INVALIDATE;case "restore"->Action.RESTORE;case "recalculate"->Action.RECALCULATE_ALL;default->throw new IllegalArgumentException("INV_SCOPE");};if(!permitted(sender,permission(action)))return;if(args.length<4)throw new IllegalArgumentException("INV_SCOPE");UUID voter=null,target=null,flag=null;int reasonAt=4;switch(args[2].toLowerCase(Locale.ROOT)){case "voter"->voter=resolve(sender,args[3]);case "target"->target=resolve(sender,args[3]);case "pair"->{if(args.length<5)throw new IllegalArgumentException("INV_SCOPE");voter=resolve(sender,args[3]);target=resolve(sender,args[4]);reasonAt=5;}case "flag"->flag=id(args[3]);default->throw new IllegalArgumentException("INV_SCOPE");}var extra=filter(sender,args);var filter=new Filter(voter,target,extra.type(),extra.status(),extra.before(),extra.after(),extra.severity(),extra.source(),flag,extra.search());boolean dry=Arrays.asList(args).contains("--dry-run");String actor=actor(sender);app.plan(action,filter,actor,reason(args,reasonAt)).whenComplete((plan,error)->plugin.onMain(()->{if(error!=null){failed(sender,error);return;}if(!sender.hasPermission("dexturreputation.admin.bulk")||!sender.hasPermission("dexturreputation.admin."+permission(action)))return;send(sender,"admin7-plan",Map.of("count",Integer.toString(plan.subjects().size()),"players",Integer.toString(plan.players().size()),"delta",plan.deltas().entrySet().stream().sorted(Map.Entry.comparingByKey()).skip((long)(page(args)-1)*app.rules().pageSize()).limit(app.rules().pageSize()).toList().toString(),"tiers",plan.tiers().stream().skip((long)(page(args)-1)*app.rules().pageSize()).limit(app.rules().pageSize()).toList().toString(),"pending",Integer.toString(plan.pendingChanges())));if(dry){send(sender,"admin7-dry-run",Map.of());return;}if(plan.subjects().size()>=app.rules().confirmThreshold())send(sender,"admin7-confirm",Map.of("token",app.token(plan),"seconds",Integer.toString(app.rules().tokenSeconds())));else{UUID operation=UUID.randomUUID();send(sender,"admin7-bulk-started",Map.of("operation",operation.toString()));finishBulk(sender,app.execute(operation,plan));}}));
    }
    @Override public List<String> onTabComplete(CommandSender sender,Command command,String alias,String[] args){var options=new ArrayList<String>();if(args.length==1){options.addAll(previous.onTabComplete(sender,command,alias,args));for(String root:ROOTS){String permission=switch(root){case "invalidate"->"vote.invalidate";case "restore"->"vote.restore";case "vote"->"vote.inspect";case "pending"->"pending.view";case "trust"->"trust.inspect";case "flags","flag"->"flags.inspect";case "relations"->"relations.inspect";case "recalculate"->"recalculate.all";case "confirm"->"bulk";default->root;};if(sender.hasPermission("dexturreputation.admin."+permission))options.add(root);}}else if(args.length==2){switch(args[0].toLowerCase(Locale.ROOT)){case "pending"->options.addAll(List.of("approve","reject"));case "recalculate"->options.addAll(List.of("reputation","trust","tier","all"));case "bulk"->options.addAll(List.of("invalidate","restore","recalculate","status","resume","cancel"));case "audit"->options.add("operation");default->{}}}if(args.length==3&&args[0].equalsIgnoreCase("history"))options.addAll(List.of("votes","admin","trust","recovery","flags"));if(args.length==3&&args[0].equalsIgnoreCase("bulk"))options.addAll(List.of("voter","target","pair","flag"));if(sender.hasPermission("dexturreputation.admin.inspect"))plugin.getServer().getOnlinePlayers().forEach(p->options.add(p.getName()));String prefix=args.length==0?"":args[args.length-1].toLowerCase(Locale.ROOT);return options.stream().distinct().filter(v->v.toLowerCase(Locale.ROOT).startsWith(prefix)).sorted().toList();}
}
